import { useState, useEffect, useRef } from 'react';
import * as LottieModule from 'lottie-react';

const Lottie = LottieModule.default?.default || LottieModule.default || LottieModule;

// Portrait screens get a re-laid-out version (generated by scripts/make-mobile-intro.py).
// Only the one that's needed is downloaded.
const isPortrait = () => window.matchMedia('(max-aspect-ratio: 1/1)').matches;
const loadAnimation = () =>
  isPortrait()
    ? import('../animations/merangkai-mobile.json')
    : import('../animations/merangkai.json');

const BG_COLOR = '#7f1f1f'; // matches the animation's background
const FAILSAFE_MS = 8000; // never leave the visitor stuck behind the splash

const IntroSplash = ({ onComplete }) => {
  const [isVisible, setIsVisible] = useState(true);
  const [isFadingOut, setIsFadingOut] = useState(false);
  const [animationData, setAnimationData] = useState(null);
  const lottieRef = useRef();
  const doneRef = useRef(false);

  const handleAnimationComplete = () => {
    if (doneRef.current) return;
    doneRef.current = true;
    setIsFadingOut(true);
    // wait for fade transition to finish before unmounting
    setTimeout(() => {
      setIsVisible(false);
      onComplete?.();
    }, 500); // matches the CSS transition duration below
  };

  useEffect(() => {
    loadAnimation()
      .then((mod) => setAnimationData(mod.default))
      .catch(handleAnimationComplete);
    const failsafe = setTimeout(handleAnimationComplete, FAILSAFE_MS);
    return () => clearTimeout(failsafe);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  if (!isVisible) return null;

  return (
    <div
      style={{
        position: 'fixed',
        inset: 0,
        width: '100vw',
        height: '100dvh',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        backgroundColor: BG_COLOR,
        zIndex: 9999,
        overflow: 'hidden',
        opacity: isFadingOut ? 0 : 1,
        transition: 'opacity 0.5s ease',
        pointerEvents: isFadingOut ? 'none' : 'auto'
      }}
    >
      {animationData && (
        <Lottie
          lottieRef={lottieRef}
          animationData={animationData}
          loop={false}
          autoplay={true}
          onComplete={handleAnimationComplete}
          rendererSettings={{ preserveAspectRatio: 'xMidYMid slice' }}
          style={{ width: '100%', height: '100%' }}
        />
      )}
    </div>
  );
};

export default IntroSplash;
